const MAX_CHANNELS:usize=8;
fn roundedShift(value:i64,shift:u6)i64{const d:i64=@as(i64,1)<<shift;if(value>=0)return @divTrunc(value,d);return -@divTrunc(-value+d-1,d);}
pub export fn depthconv(values:?[*]const i64,length:usize,output:?[*]u8,capacity:usize)i64{const v=values orelse return -1;if(length<1 or length>1+11*MAX_CHANNELS)return -1;const cc=v[0];if(cc<1 or cc>MAX_CHANNELS or length!=1+11*@as(usize,@intCast(cc)))return -1;const c:usize=@intCast(cc);for(1..1+8*c)|i|if(v[i] < -128 or v[i]>127)return -1;for(1+8*c..1+9*c)|i|if(v[i] < -1_000_000 or v[i]>1_000_000)return -1;for(1+9*c..1+10*c)|i|if(v[i]<0 or v[i]>2_147_483_647)return -1;for(1+10*c..length)|i|if(v[i] < -8 or v[i]>0)return -1;const out=output orelse return -2;if(capacity<c)return -2;for(0..c)|ch|{var acc:i32=0;for(0..4)|row|acc+=@as(i32,@intCast(v[1+row*c+ch]+128))*@as(i32,@intCast(v[1+4*c+row*c+ch]));acc+=@intCast(v[1+8*c+ch]);const shift:u6=@intCast(31-v[1+10*c+ch]);const round:i64=@as(i64,1)<<(shift-1);var scaled=roundedShift(@as(i64,acc)*v[1+9*c+ch]+round,shift);if(scaled>127)scaled=127;if(scaled< -128)scaled=-128;out[ch]=@bitCast(@as(i8,@intCast(scaled)));}return @intCast(c);}
